INSERT INTO discovery_questions (id, persona, question, subtitle, options, condition_tool_ids, condition_type) VALUES
('dq-llm-usage', 'ALL', 'Comment utilises-tu tes LLMs au quotidien ?', 'Ça nous aide à savoir si tu as vraiment besoin de plusieurs abonnements', '[{"label":"Surtout du chat et des questions","impact":"review"},{"label":"Génération de contenu (articles, emails)","impact":"keep"},{"label":"Code et technique","impact":"keep"},{"label":"Je teste mais j''utilise peu","impact":"cancel"}]', '["chatgpt","claude","gemini","perplexity","deepseek"]', 'any'),
('dq-design-collab', 'SOFIA', 'Tu collabores avec des clients ou une équipe dans Figma ?', 'Le plan gratuit peut suffire pour le travail solo', '[{"label":"Oui, collaboration quotidienne","impact":"keep"},{"label":"Parfois, avec quelques clients","impact":"review"},{"label":"Non, je travaille seul(e)","impact":"review"}]', '["figma"]', 'any'),
('dq-adobe-usage', 'SOFIA', 'Tu utilises combien d''apps Adobe régulièrement ?', 'Si 3+ apps, le pack complet est plus rentable', '[{"label":"1-2 apps seulement","impact":"review"},{"label":"3-4 apps","impact":"keep"},{"label":"5+ apps","impact":"keep"}]', '["photoshop","illustrator","premiere-pro","after-effects","lightroom","indesign","adobe-creative-cloud"]', 'any'),
('dq-automation-volume', 'ALL', 'Combien de workflows automatisés as-tu actifs ?', 'Le nombre de scénarios détermine si le plan payant vaut le coup', '[{"label":"Moins de 5","impact":"review"},{"label":"5 à 20","impact":"keep"},{"label":"Plus de 20","impact":"keep"},{"label":"Je ne sais pas","impact":"review"}]', '["zapier","make","n8n"]', 'any'),
('dq-hosting-traffic', 'THEO', 'Quel volume de trafic sur tes apps déployées ?', 'Le bon plan dépend de ton trafic réel', '[{"label":"Side project, peu de trafic","impact":"review"},{"label":"Quelques milliers d''utilisateurs","impact":"keep"},{"label":"Production sérieuse, gros trafic","impact":"keep"}]', '["vercel","netlify","railway","render","heroku","fly-io"]', 'any'),
('dq-crm-contacts', 'MARC', 'Combien de contacts actifs dans ton CRM ?', 'En dessous de 500 contacts, le plan gratuit suffit souvent', '[{"label":"Moins de 100","impact":"review"},{"label":"100 à 1000","impact":"keep"},{"label":"Plus de 1000","impact":"keep"}]', '["hubspot","pipedrive","folk","close"]', 'any'),
('dq-newsletter-subs', 'ALIX', 'Combien d''abonnés à ta newsletter ?', 'Le prix monte vite avec le nombre d''abonnés', '[{"label":"Moins de 500","impact":"review"},{"label":"500 à 5000","impact":"keep"},{"label":"Plus de 5000","impact":"keep"}]', '["substack","convertkit","mailchimp","brevo","beehiiv"]', 'any'),
('dq-storage-usage', 'ALL', 'Tu utilises combien de Go de stockage cloud ?', 'Beaucoup paient pour du stockage qu''ils n''utilisent pas', '[{"label":"Moins de 15 Go (gratuit suffit)","impact":"review"},{"label":"15 à 100 Go","impact":"keep"},{"label":"Plus de 100 Go","impact":"keep"},{"label":"Aucune idée","impact":"review"}]', '["google-drive","dropbox","onedrive"]', 'any');
